🧰️framework/🔨️modules/🛠️tool-machine/🧪️t:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://json.schemas.assets.semio-tech.com/test/tool-machine/corpora.json",
  "title": "ToolMachineCorpora",
  "description": "🧪️ Test-owned corpus envelopes and normative constants for the transaction, scrub and typing laws. Runtime event and yield references are resolved through the domain schema. Scenario execution is judged independently by xstate and fast-check.",
  "$defs": {
    "TransactionLawFixture": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema",
        "states",
        "yieldKinds",
        "refusals",
        "abortReasons",
        "matrix",
        "cases",
        "ids",
        "gesture",
        "invariants"
      ],
      "properties": {
        "schema": {
          "const": "semio.framework.tool-machine.transaction-law.v1"
        },
        "states": {
          "const": [
            "open",
            "committed",
            "aborted"
          ]
        },
        "yieldKinds": {
          "const": [
            "upsert",
            "retract",
            "commit",
            "abort"
          ]
        },
        "refusals": {
          "const": [
            "toolTransaction.closed",
            "toolTransaction.unclosed"
          ]
        },
        "abortReasons": {
          "const": [
            "tool",
            "blur",
            "captureLost",
            "baseMoved",
            "frozen",
            "retired"
          ]
        },
        "matrix": {
          "type": "array",
          "items": {
            "oneOf": [
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "from",
                  "yield",
                  "to"
                ],
                "properties": {
                  "from": {
                    "enum": [
                      "open",
                      "committed",
                      "aborted"
                    ]
                  },
                  "yield": {
                    "enum": [
                      "upsert",
                      "retract",
                      "commit",
                      "abort"
                    ]
                  },
                  "to": {
                    "enum": [
                      "open",
                      "committed",
                      "aborted"
                    ]
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "from",
                  "yield",
                  "refusal"
                ],
                "properties": {
                  "from": {
                    "enum": [
                      "open",
                      "committed",
                      "aborted"
                    ]
                  },
                  "yield": {
                    "enum": [
                      "upsert",
                      "retract",
                      "commit",
                      "abort"
                    ]
                  },
                  "refusal": {
                    "enum": [
                      "toolTransaction.closed",
                      "toolTransaction.unclosed"
                    ]
                  }
                }
              }
            ]
          },
          "minItems": 12,
          "maxItems": 12
        },
        "cases": {
          "type": "array",
          "items": {
            "type": "object"
          }
        },
        "ids": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "actor",
              "clock",
              "tool",
              "id"
            ],
            "properties": {
              "actor": {
                "type": "string"
              },
              "clock": {
                "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/HybridLogicalTimestamp"
              },
              "tool": {
                "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/ToolId"
              },
              "id": {
                "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/TransactionId"
              }
            }
          }
        },
        "gesture": {
          "type": "object",
          "properties": {
            "variants": {
              "type": "array",
              "items": {
                "type": "object",
                "required": [
                  "chart",
                  "scenarios"
                ],
                "properties": {
                  "scenarios": {
                    "type": "array",
                    "items": {
                      "$ref": "#/$defs/GestureScenario"
                    }
                  },
                  "chart": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/GestureChart"
                  }
                }
              }
            }
          }
        },
        "invariants": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "id",
              "statement"
            ],
            "properties": {
              "id": {
                "type": "string"
              },
              "statement": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "ScrubLawFixture": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema",
        "args",
        "phases",
        "chart",
        "actor",
        "scenarios"
      ],
      "properties": {
        "schema": {
          "const": "semio.framework.tool-machine.scrub-law.v1"
        },
        "args": {
          "const": {
            "gesture": "gesture",
            "commit": "commit",
            "abort": "abort"
          }
        },
        "phases": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "args",
              "phase"
            ],
            "properties": {
              "args": {
                "type": "object"
              },
              "phase": {
                "anyOf": [
                  {
                    "type": "null"
                  },
                  {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/ScrubPhase"
                  }
                ]
              }
            }
          }
        },
        "chart": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "id",
            "fingerprint",
            "manifestJson",
            "states",
            "initial",
            "transitions"
          ],
          "properties": {
            "id": {
              "type": "string"
            },
            "fingerprint": {
              "type": "string",
              "pattern": "^[0-9]+$"
            },
            "manifestJson": {
              "type": "string"
            },
            "states": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "initial": {
              "type": "string"
            },
            "events": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "transitions": {
              "type": "array",
              "items": {
                "type": "object"
              }
            }
          }
        },
        "actor": {
          "type": "string"
        },
        "scenarios": {
          "type": "array",
          "items": {
            "type": "object"
          }
        }
      }
    },
    "TypingLawFixture": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema",
        "args",
        "idleMs",
        "reasons",
        "chart",
        "phases",
        "algebra",
        "actor",
        "scenarios"
      ],
      "properties": {
        "schema": {
          "const": "semio.framework.tool-machine.typing-law.v1"
        },
        "args": {
          "const": {
            "buffer": "typing",
            "commit": "typingCommit"
          }
        },
        "idleMs": {
          "const": 750
        },
        "reasons": {
          "const": [
            "idle",
            "selectionJump",
            "blur",
            "enter",
            "hidden",
            "apply",
            "otherVerb"
          ]
        },
        "chart": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "id",
            "fingerprint",
            "manifestJson",
            "states",
            "initial",
            "transitions"
          ],
          "properties": {
            "id": {
              "type": "string"
            },
            "fingerprint": {
              "type": "string",
              "pattern": "^[0-9]+$"
            },
            "manifestJson": {
              "type": "string"
            },
            "states": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "initial": {
              "type": "string"
            },
            "events": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "transitions": {
              "type": "array",
              "items": {
                "type": "object"
              }
            }
          }
        },
        "phases": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "args",
              "phase"
            ],
            "properties": {
              "args": {
                "type": "object"
              },
              "phase": {
                "anyOf": [
                  {
                    "type": "null"
                  },
                  {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/TypingPhase"
                  }
                ]
              }
            }
          }
        },
        "algebra": {
          "type": "object"
        },
        "actor": {
          "type": "string"
        },
        "scenarios": {
          "type": "array",
          "items": {
            "type": "object"
          }
        }
      }
    },
    "GestureScenario": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "steps"
      ],
      "properties": {
        "name": {
          "type": "string"
        },
        "steps": {
          "type": "array",
          "items": {
            "oneOf": [
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "event",
                  "clock",
                  "state",
                  "step"
                ],
                "properties": {
                  "event": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/GestureEvent"
                  },
                  "clock": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/HybridLogicalTimestamp"
                  },
                  "state": {
                    "type": "string",
                    "minLength": 1
                  },
                  "step": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/ToolStep"
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "event",
                  "clock",
                  "state",
                  "refusal"
                ],
                "properties": {
                  "event": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/GestureEvent"
                  },
                  "clock": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/HybridLogicalTimestamp"
                  },
                  "state": {
                    "type": "string",
                    "minLength": 1
                  },
                  "refusal": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/ToolRefusal"
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "host",
                  "reason",
                  "state",
                  "step"
                ],
                "properties": {
                  "host": {
                    "const": "abort"
                  },
                  "reason": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/ToolAbortReason"
                  },
                  "state": {
                    "type": "string",
                    "minLength": 1
                  },
                  "step": {
                    "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/ToolStep"
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "host",
                  "state"
                ],
                "properties": {
                  "host": {
                    "const": "reset"
                  },
                  "state": {
                    "type": "string",
                    "minLength": 1
                  },
                  "dropped": {
                    "anyOf": [
                      {
                        "$ref": "https://json.schemas.assets.semio-tech.com/framework/tool-machine/schema.json#/$defs/TransactionRef"
                      },
                      {
                        "type": "null"
                      }
                    ]
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "host",
                  "state"
                ],
                "properties": {
                  "host": {
                    "const": "resume"
                  },
                  "state": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              }
            ]
          }
        }
      }
    }
  }
}

🌎️hub/🧬️schema/🤝️two-client-document-v1/:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://json.schemas.assets.semio-tech.com/hub/two-client-document/schema.json",
  "title": "TwoClientDocumentScenarioV1",
  "$defs": {
    "TwoClientDocumentScenarioV1": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema",
        "version",
        "authors",
        "artifactKindId",
        "surfaceId",
        "spaceName",
        "command",
        "growth",
        "presence",
        "agent",
        "directoryPages",
        "shutdown",
        "steps",
        "expectations"
      ],
      "properties": {
        "schema": {
          "const": "semio.hub.two-client-document-scenario/v1"
        },
        "version": {
          "const": 1
        },
        "authors": {
          "type": "array",
          "minItems": 2,
          "maxItems": 2,
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 64
          }
        },
        "artifactKindId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "surfaceId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "spaceName": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
        },
        "command": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "diffSchema",
            "diffValue",
            "inverseValue",
            "batchId",
            "mutationIdPrefix"
          ],
          "properties": {
            "diffSchema": {
              "const": "db.pathmap.v1"
            },
            "diffValue": {
              "type": "object"
            },
            "inverseValue": {
              "type": "object"
            },
            "batchId": {
              "type": "integer",
              "minimum": 1
            },
            "mutationIdPrefix": {
              "type": "string",
              "minLength": 1,
              "maxLength": 32
            }
          }
        },
        "growth": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "editsBeforeRestart",
            "editsAfterRestart",
            "payloadBytes",
            "distinctPaths",
            "batchIdBase",
            "mutationIdPrefix"
          ],
          "properties": {
            "editsBeforeRestart": {
              "type": "integer",
              "minimum": 1,
              "maximum": 100000
            },
            "editsAfterRestart": {
              "type": "integer",
              "minimum": 1,
              "maximum": 100000
            },
            "payloadBytes": {
              "type": "integer",
              "minimum": 1,
              "maximum": 1048576
            },
            "distinctPaths": {
              "type": "integer",
              "minimum": 1,
              "maximum": 64,
              "x-semio-note": "a pathmap document retains at most 64 distinct paths (RETAINED_STATE_ENTRIES)"
            },
            "batchIdBase": {
              "type": "integer",
              "minimum": 1
            },
            "mutationIdPrefix": {
              "type": "string",
              "minLength": 1,
              "maxLength": 64
            }
          }
        },
        "presence": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "lane",
            "labelA",
            "leaseTtlMs",
            "hoveredPath"
          ],
          "properties": {
            "lane": {
              "const": "preview"
            },
            "labelA": {
              "type": "string",
              "minLength": 1,
              "maxLength": 64
            },
            "leaseTtlMs": {
              "type": "integer",
              "minimum": 1000,
              "maximum": 120000
            },
            "hoveredPath": {
              "type": "string",
              "minLength": 1,
              "maxLength": 256
            }
          }
        },
        "agent": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "agentLabel",
            "audience",
            "ttlSecs",
            "agentInstanceId",
            "revocationWithinMs",
            "closeCode",
            "refusedStatus",
            "reexchangeStatus",
            "reexchangeError",
            "executionTargetWithinMs",
            "diffValue"
          ],
          "x-semio-note": "a delegated agent on the same document: revoking its delegation closes its open socket, drops it from the other client's roster and refuses its next request (401), all within revocationWithinMs; the revoked delegation itself is refused 403 delegation-revoked, the cause a holder of its secret is entitled to know",
          "properties": {
            "agentLabel": {
              "type": "string",
              "minLength": 1,
              "maxLength": 64
            },
            "audience": {
              "enum": [
                "read",
                "edit"
              ]
            },
            "ttlSecs": {
              "type": "integer",
              "minimum": 60,
              "maximum": 86400
            },
            "agentInstanceId": {
              "type": "string",
              "minLength": 1,
              "maxLength": 128
            },
            "revocationWithinMs": {
              "type": "integer",
              "minimum": 100,
              "maximum": 60000
            },
            "closeCode": {
              "const": 4401
            },
            "refusedStatus": {
              "const": 401
            },
            "reexchangeStatus": {
              "const": 403
            },
            "reexchangeError": {
              "const": "delegation-revoked"
            },
            "executionTargetWithinMs": {
              "type": "integer",
              "minimum": 100,
              "maximum": 10000,
              "x-semio-note": "after the agent's own commit, with its socket still open, the agent's execution-target manifest and descriptor answer 200 within this bound (G10: 503 deadline-exceeded for minutes on the exclusive-gate hub)"
            },
            "diffValue": {
              "type": "object",
              "minProperties": 1,
              "maxProperties": 8
            }
          }
        },
        "directoryPages": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "spaces",
            "pageBudgetMs",
            "samples"
          ],
          "x-semio-note": "author A owns this many more spaces; its space list (best of samples) and every directory event page answer within pageBudgetMs (WG8 on 7800: 25–58 s for 82 spaces)",
          "properties": {
            "spaces": {
              "type": "integer",
              "minimum": 100,
              "maximum": 1000
            },
            "pageBudgetMs": {
              "type": "integer",
              "minimum": 50,
              "maximum": 2000
            },
            "samples": {
              "type": "integer",
              "minimum": 1,
              "maximum": 10
            }
          }
        },
        "shutdown": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "closeCode",
            "gracefulExitWithinMs",
            "restartWithinMs",
            "reopenWithinMs",
            "crashReleaseSlackMs",
            "databaseClosedMarker",
            "liveWriterProbe"
          ],
          "properties": {
            "closeCode": {
              "const": 1012
            },
            "gracefulExitWithinMs": {
              "type": "integer",
              "minimum": 1000,
              "maximum": 120000
            },
            "crashReleaseSlackMs": {
              "type": "integer",
              "minimum": 1000,
              "maximum": 120000
            },
            "databaseClosedMarker": {
              "type": "string",
              "minLength": 1,
              "maxLength": 64
            },
            "liveWriterProbe": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "postgres",
                "neo4j"
              ],
              "properties": {
                "postgres": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 512
                },
                "neo4j": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 512
                }
              }
            },
            "restartWithinMs": {
              "type": "integer",
              "minimum": 1,
              "maximum": 60000
            },
            "reopenWithinMs": {
              "type": "integer",
              "minimum": 1000,
              "maximum": 120000,
              "x-semio-note": "a restarted hub welcomes the first socket of a grown document within this bound (the document's WAL replays on that open)"
            }
          }
        },
        "steps": {
          "type": "array",
          "minItems": 8,
          "items": {
            "type": "string"
          }
        },
        "expectations": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "bReceivesCommandsEnvelope",
            "ackStagesIncludeApplied",
            "frontierDocumentIdIsPlainArtifactId",
            "presencePeerActorMatchesA",
            "presenceJoinReplayShowsA",
            "reconnectDeliversMissedOrRebootstrap",
            "restartPreservesArtifactAndFrontier",
            "lateJoinerCatchesUp",
            "presenceLeaveDropsPeer",
            "presenceLeaseExpiryStripsA",
            "gracefulShutdownClosesSocketsAndReleasesWriters",
            "crashReleasesWritersPerBackendContract",
            "revocationEndsAgentSession"
          ],
          "properties": {
            "bReceivesCommandsEnvelope": {
              "type": "boolean"
            },
            "ackStagesIncludeApplied": {
              "type": "boolean"
            },
            "frontierDocumentIdIsPlainArtifactId": {
              "type": "boolean"
            },
            "presencePeerActorMatchesA": {
              "type": "boolean"
            },
            "reconnectDeliversMissedOrRebootstrap": {
              "type": "boolean"
            },
            "restartPreservesArtifactAndFrontier": {
              "type": "boolean"
            },
            "presenceJoinReplayShowsA": {
              "type": "boolean"
            },
            "lateJoinerCatchesUp": {
              "type": "boolean"
            },
            "presenceLeaveDropsPeer": {
              "type": "boolean"
            },
            "presenceLeaseExpiryStripsA": {
              "type": "boolean"
            },
            "gracefulShutdownClosesSocketsAndReleasesWriters": {
              "type": "boolean"
            },
            "crashReleasesWritersPerBackendContract": {
              "type": "boolean"
            },
            "revocationEndsAgentSession": {
              "type": "boolean"
            }
          }
        },
        "nonclaims": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    }
  }
}

🌎️hub/🧬️schema/📈️document-growth-v1/🔣️.j:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://json.schemas.assets.semio-tech.com/hub/document-growth/schema.json",
  "title": "DocumentGrowthScenarioV1",
  "description": "One real-binary hub scenario: documents created through the creation catalog, grown concurrently with chained edits, the hub restarted on the same data root, every document reopened and edited again. A document stays writable as it grows.",
  "$ref": "#/$defs/DocumentGrowthScenarioV1",
  "$defs": {
    "DocumentGrowthScenarioV1": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schema", "version", "author", "spaceName", "documents", "editsAfterRestart", "command", "bounds", "shutdown", "refusalMarkers", "steps"],
      "properties": {
        "schema": { "const": "semio.hub.document-growth-scenario/v1" },
        "version": { "const": 1 },
        "author": { "type": "string", "minLength": 1, "maxLength": 64 },
        "spaceName": { "type": "string", "minLength": 1, "maxLength": 128 },
