      const result = M.ToolRunMachine.apply(slot, matrixEvent(row.event, 7n, 2));
      const label = `${row.from} × ${row.event}`;
      if ("rejection" in row) {
        expect(result.ok ? "accepted" : result.rejection, label).toBe(row.rejection);
        continue;
      }
      expect(result.ok, label).toBe(true);
